import java.util.Arrays;
import java.util.Comparator;

public static void solve(FastScanner sc, FastPrintStream pw) throws Exception {
    int times = sc.nextInt();
    for (int time = 0; time < times; time++) {
        long a[] = new long[5];
        long p[] = new long[5];
        Arrays.setAll(a, i -> sc.nextLong());
        Arrays.setAll(p, i -> sc.nextLong());
        long now = 0;
        long count = 0;
        for (int i = 0; i < 5; i++) {
            now += a[i] * (i + 1);
            count += a[i];
        }
        if (now / count >= 3) {
            pw.println(0);
            continue;
        }
        long sa = 3 * count - now;
        long totalCost = 0;
        long[][] costPerStar = new long[5][2];
        for (int i = 0; i < 5; i++) {
            costPerStar[i][0] = p[i];
            costPerStar[i][1] = i + 1;
        }
        Arrays.sort(costPerStar, Comparator.comparingLong(o -> o[0]));
        for (long[] cost : costPerStar) {
            long starsNeeded = sa / cost[1];
            if (starsNeeded > 0) {
                long costForStars = Math.min(starsNeeded, a[(int) cost[1] - 1]) * cost[0];
                totalCost += costForStars;
                sa -= starsNeeded * cost[1];
            }
            if (sa <= 0) break;
        }
        pw.println(totalCost);
    }
}
